import fs from 'node:fs'; import assert from 'node:assert/strict'; import {createHash} from 'node:crypto';
const h=x=>createHash('sha256').update(JSON.stringify(x)).digest('hex');
const m=JSON.parse(fs.readFileSync('MANIFEST.json','utf8'));
const b=JSON.parse(fs.readFileSync('.ufo/scopes/shokunin-12h-20261014/evidence/manifest-before.json','utf8'));
const before=h(m.rounds.slice(0,b.rounds));
const other=h(Object.fromEntries(Object.entries(m).filter(([k])=>k!=='rounds')));
assert.equal(before,b.rounds_sha256,'existing round prefix changed');
assert.equal(other,b.other_fields_sha256,'roster or other manifest fields changed');
assert.equal(m.rounds.length,b.rounds+1,'exactly one ops note appended');
const e=m.rounds.at(-1);
assert.equal(e.type,'ops'); assert.equal(e.status,'blocked');
assert.equal(e.report,'.ufo/reports/shokunin-12h-20261014-preflight.md');
assert.equal(Object.hasOwn(e,'lanes'),false,'no fictitious child-round statuses');
assert.deepEqual(e.minted,[]); assert.deepEqual(e.promotions,[]);
assert.ok(fs.statSync(e.report).isFile(),'operator report exists');
console.log(JSON.stringify({verdict:'LEDGER_INTEGRITY: PASS',previous_entries:b.rounds,current_entries:m.rounds.length,prefix_sha256:before,other_fields_sha256:other,new_entry_sha256:h(e),roster_unchanged:true,child_round_statuses_added:false,mints_added:0,report:e.report}));
